@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@600;700&family=Nunito:wght@700;800;900&display=swap');

:root { --ink:#17375a; --blue:#78d3ef; --yellow:#ffd85a; }
* { box-sizing:border-box; }
html, body { width:100%; height:100%; margin:0; overflow:hidden; }
body { font-family:'Nunito',sans-serif; background:#94daf2; color:var(--ink); }
button { font:inherit; }
.game-shell { position:relative; width:100%; height:100%; min-height:520px; display:grid; grid-template-rows:82px 1fr 48px; background:linear-gradient(180deg,#7fd4f2 0%,#bcecff 72%,#dcf4a7 100%); }
.sky-glow { position:absolute; width:420px; height:420px; border-radius:50%; right:-120px; top:-210px; background:rgba(255,255,220,.42); filter:blur(8px); }
.hud { z-index:20; display:flex; align-items:center; justify-content:space-between; padding:12px clamp(18px,4vw,58px); background:rgba(255,255,255,.86); border-bottom:3px solid rgba(23,55,90,.1); backdrop-filter:blur(10px); }
.brand { display:flex; align-items:center; gap:10px; font-family:'Fredoka',sans-serif; font-size:clamp(18px,2.2vw,29px); letter-spacing:-1px; }
.brand b { color:#f05b69; }.brand-balloon { display:inline-grid; place-items:center; width:48px; height:48px; border-radius:50%; background:#fff3b7; font-size:33px; box-shadow:0 4px 0 #edcf65; }
.stats { display:flex; align-items:center; gap:clamp(16px,3vw,38px); }.stat { min-width:68px; display:flex; flex-direction:column; align-items:center; line-height:1.05; }.stat small { color:#7591a7; font-size:10px; letter-spacing:1.8px; }.stat strong { font-family:'Fredoka',sans-serif; font-size:25px; }.lives strong { color:#f05b69; font-size:20px; letter-spacing:3px; }
.playfield { position:relative; overflow:hidden; isolation:isolate; }
.cloud { position:absolute; width:150px; height:38px; border-radius:40px; background:rgba(255,255,255,.78); z-index:-1; }.cloud:before,.cloud:after { content:''; position:absolute; border-radius:50%; background:inherit; }.cloud:before { width:60px;height:60px;left:20px;bottom:8px; }.cloud:after { width:75px;height:75px;right:18px;bottom:4px; }.cloud-a { left:8%;top:15%;transform:scale(.75); }.cloud-b { right:16%;top:24%;transform:scale(.58); }.cloud-c { left:52%;top:8%;transform:scale(.42); opacity:.8; }
.hills { position:absolute; left:-5%; right:-5%; bottom:-1px; z-index:-1; }.hill-back { height:25%; background:#78c982; clip-path:polygon(0 44%,12% 20%,24% 52%,38% 15%,53% 49%,67% 24%,82% 47%,100% 18%,100% 100%,0 100%); opacity:.72; }.hill-front { height:18%; background:#4cab65; clip-path:polygon(0 46%,13% 25%,28% 55%,43% 21%,58% 48%,72% 15%,88% 52%,100% 27%,100% 100%,0 100%); }
.panel { position:absolute; z-index:10; left:50%; top:47%; transform:translate(-50%,-50%); width:min(470px,calc(100% - 32px)); text-align:center; padding:28px 30px 22px; border-radius:28px; background:rgba(255,255,255,.94); border:3px solid rgba(255,255,255,.9); box-shadow:0 16px 0 rgba(45,133,151,.12),0 24px 50px rgba(32,96,125,.18); }.panel.hidden { display:none; }.panel-balloon { position:absolute; width:75px;height:75px; left:50%; top:-50px; transform:translateX(-50%) rotate(-5deg); display:grid;place-items:center;font-size:62px; filter:drop-shadow(0 7px 3px rgba(34,93,123,.15)); }.eyebrow { margin:17px 0 6px; color:#ee6a70; font-size:12px; letter-spacing:3px; font-weight:900; }.panel h1 { margin:0 0 10px; font-family:'Fredoka',sans-serif; font-size:clamp(34px,6vw,52px); letter-spacing:-2px; }.instructions { margin:0 0 20px; color:#66809a; line-height:1.55; font-size:15px; }.primary-button { width:min(260px,100%); height:54px; border:0; border-radius:16px; background:#f05f68; color:white; font-size:16px; font-weight:900; letter-spacing:1px; box-shadow:0 7px 0 #c94355,0 12px 22px rgba(225,91,104,.24); cursor:pointer; transition:.12s transform,.12s box-shadow; }.primary-button span { float:right;margin-right:16px;font-size:22px }.primary-button:hover { transform:translateY(-2px); box-shadow:0 9px 0 #c94355,0 14px 24px rgba(225,91,104,.24); }.primary-button:active { transform:translateY(5px); box-shadow:0 2px 0 #c94355; }.tip { margin:15px 0 0; color:#94a3af; font-size:11px; }kbd { padding:3px 7px;border-radius:5px;background:#edf3f5;border:1px solid #d4e0e5;box-shadow:0 2px 0 #d4e0e5;font-size:9px; }
.final-score { display:inline-flex; flex-direction:column; align-items:center; margin:3px 0 18px; }.final-score small { color:#7591a7;font-size:10px;letter-spacing:2px }.final-score strong { font-family:'Fredoka';font-size:38px;color:#f05f68 }
.balloon { --c:#ef626b; --c2:#ff8b91; position:absolute; width:68px;height:86px; border-radius:50% 50% 48% 48%; background:radial-gradient(circle at 32% 25%,rgba(255,255,255,.82) 0 7%,transparent 8%),linear-gradient(145deg,var(--c2),var(--c)); box-shadow:inset -8px -8px 14px rgba(120,32,70,.12),0 10px 14px rgba(41,108,130,.12); cursor:pointer; border:0; padding:0; touch-action:manipulation; z-index:5; animation:float-in .22s ease-out both; }.balloon:after { content:'';position:absolute;left:50%;bottom:-8px;transform:translateX(-50%);border-left:7px solid transparent;border-right:7px solid transparent;border-top:12px solid var(--c); }.balloon:before { content:'';position:absolute;width:1.5px;height:42px;left:50%;bottom:-48px;background:rgba(70,94,105,.42);transform:rotate(4deg);transform-origin:top; }.balloon.popping { pointer-events:none; animation:pop .18s ease-in forwards; }
.score-pop { position:absolute; z-index:30; color:#17375a; font-family:'Fredoka'; font-size:19px; font-weight:900; text-shadow:0 2px 0 white; pointer-events:none; animation:score-float .65s ease-out forwards; }
.controls { z-index:20; display:flex; align-items:center; justify-content:center; gap:55px; background:rgba(232,248,215,.9); border-top:2px solid rgba(76,144,87,.12); color:#78928a;font-size:11px;letter-spacing:1px;text-transform:uppercase }.controls b { color:#4e7c66 }
@keyframes float-in { from { opacity:0; transform:scale(.25) } to { opacity:1; transform:scale(1) } }@keyframes pop { 0%{transform:scale(1)} 35%{transform:scale(1.22)} 100%{transform:scale(.05);opacity:0} }@keyframes score-float { to { transform:translateY(-38px) scale(.85); opacity:0 } }
@media (max-width:620px) { .game-shell { grid-template-rows:68px 1fr 42px }.hud { padding:8px 12px }.brand { gap:6px }.brand-balloon { width:40px;height:40px;font-size:27px }.brand>span:last-child { max-width:72px;font-size:16px;line-height:.9 }.stats { gap:7px }.stat { min-width:48px }.stat strong { font-size:21px }.lives strong { font-size:15px }.panel { top:45%; }.instructions { font-size:13px }.controls { gap:24px }.cloud-b { right:-30px } }
@media (max-height:600px) { .game-shell { min-height:480px }.panel { transform:translate(-50%, -53%) scale(.86); }.hud { height:68px }.game-shell { grid-template-rows:68px 1fr 40px } }

const field = document.querySelector('#playfield');
const startPanel = document.querySelector('#startPanel');
const overPanel = document.querySelector('#gameOverPanel');
const scoreEl = document.querySelector('#score');
const bestEl = document.querySelector('#best');
const livesEl = document.querySelector('#lives');
const finalScoreEl = document.querySelector('#finalScore');

let score = 0;
let lives = 3;
let playing = false;
let spawnTimer = null;
let raf = null;
let balloons = [];
let best = Number(localStorage.getItem('balloon-best') || 0);
bestEl.textContent = best;

const colors = [
  ['#ef626b','#ff969b'], ['#5dace8','#92cafa'], ['#ffc84b','#ffe48a'],
  ['#9b75d5','#c5a4ef'], ['#53bfa1','#89dcca'], ['#f49b52','#ffc58e']
];

function startGame() {
  balloons.forEach(b => b.el.remove());
  balloons = [];
  score = 0; lives = 3; playing = true;
  scoreEl.textContent = '0'; updateLives();
  startPanel.classList.add('hidden'); overPanel.classList.add('hidden');
  clearTimeout(spawnTimer); cancelAnimationFrame(raf);
  spawnBalloon();
  spawnLoop();
  raf = requestAnimationFrame(tick);
}

function updateLives() { livesEl.textContent = lives > 0 ? '♥ '.repeat(lives).trim() : '♡'; }

function spawnLoop() {
  if (!playing) return;
  spawnBalloon();
  const delay = Math.max(430, 1050 - score * 11);
  spawnTimer = setTimeout(spawnLoop, delay);
}

function spawnBalloon() {
  if (!playing) return;
  const rect = field.getBoundingClientRect();
  const el = document.createElement('button');
  el.className = 'balloon'; el.setAttribute('aria-label','Pop balloon');
  const palette = colors[Math.floor(Math.random() * colors.length)];
  el.style.setProperty('--c', palette[0]); el.style.setProperty('--c2', palette[1]);
  const size = rect.width < 600 ? 58 : 68;
  el.style.width = size + 'px'; el.style.height = (size * 1.27) + 'px';
  const x = 18 + Math.random() * Math.max(1, rect.width - size - 36);
  el.style.left = x + 'px';
  el.style.top = rect.height + 20 + 'px';

  const data = {
    el, x, y: rect.height + 20,
    speed: (58 + Math.random() * 38) + Math.min(score * 1.1, 55),
    wobble: Math.random() * Math.PI * 2,
    popped:false
  };
  el.addEventListener('pointerdown', e => { e.preventAnimation; popBalloon(data, e); });
  field.appendChild(el);
  balloons.push(data);
}

function popBalloon(data, event) {
  if (!playing || data.popped) return;
  data.popped = true;
  data.el.classList.add('popping');
  score += 10;
  scoreEl.textContent = score;
  const rect = field.getBoundingClientRect();
  const x = event?.clientX - rect.left;
  const y = event?.clientY - rect.top;
  const pop = document.createElement('div');
  pop.className = 'score-pop'; pop.textContent = '+10';
  pop.style.left = ((x || data.x) - 15) + 'px'; pop.style.top = ((y || data.y) - 10) + 'px';
  field.appendChild(pop);
  setTimeout(() => { pop.remove(); data.el.remove(); }, 650);
  balloons = balloons.filter(b => b !== data);
}

function tick(now) {
  if (!playing) return;
  const rect = field.getBoundingClientRect();
  for (let i = balloons.length - 1; i >= 0; i--) {
    const b = balloons[i];
    if (b.popped) continue;
    b.y -= b.speed / 60;
    b.wobble += 0.025;
    const drift = Math.sin(b.wobble) * 10;
    b.el.style.transform = `translateX(${drift}px)`;
    b.el.style.top = b.y + 'px';
    if (b.y < -110) {
      b.el.remove(); balloons.splice(i, 1);
      lives -= 1; updateLives();
      if (lives <= 0) endGame();
    }
  }
  raf = requestAnimationFrame(tick);
}

function endGame() {
  playing = false;
  clearTimeout(spawnTimer); cancelAnimationFrame(raf);
  balloons.forEach(b => b.el.remove()); balloons = [];
  if (score > best) { best = score; localStorage.setItem('balloon-best', String(best)); bestEl.textContent = best; }
  finalScoreEl.textContent = score;
  setTimeout(() => overPanel.classList.remove('hidden'), 250);
}

document.querySelector('#startButton').addEventListener('click', startGame);
document.querySelector('#restartButton').addEventListener('click', startGame);
window.addEventListener('keydown', e => {
  if (e.code === 'Space') { e.preventDefault(); if (!playing) startGame(); }
});

